    loading: boolean,
    /** @maxLength 2048 */
    loadError?: string,
    canGoBack: boolean,
    canGoForward: boolean,
    /** @integer @minimum 0 */
    generation: number,
  },
  messages: Array<{
      /** @maxLength 2048 */
      id: string,
      timestampMs: number,
      level: "debug" | "info" | "warning" | "error",
      /** @maxLength 100000 */
