Read file C:\Users\wilso\Documents\APPS\origen_app_erp\ORIGEN\lib\apiAuth.ts, lines 1-149
1: import type { NextRequest } from 'next/server';
2: 
3: /**
4:  * Autenticación de rutas API con el ID token de Firebase.
5:  *
6:  * El repositorio no tiene credenciales de `firebase-admin` (no hay service
7:  * account), así que la verificación se hace contra Identity Toolkit
8:  * (`accounts:lookup`), que valida firma, emisor y expiración del token usando
9:  * la API key pública del proyecto. Es *fail-closed*: ante cualquier duda el
10:  * resultado es no autenticado, nunca acceso libre.
11:  */
12: 
13: export interface ApiUser {
14:   uid: string;
15:   email: string | null;
16:   emailVerified: boolean;
17:   displayName: string | null;
18: }
19: 
20: export type ApiAuthResult =
21:   | { ok: true; user: ApiUser; idToken: string }
22:   | { ok: false; status: 401 | 403 | 503; message: string };
23: 
24: const IDENTITY_TOOLKIT_URL = 'https://identitytoolkit.googleapis.com/v1/accounts:lookup';
25: 
26: interface IdentityToolkitAccount {
27:   localId?: unknown;
28:   email?: unknown;
29:   emailVerified?: unknown;
30:   displayName?: unknown;
31: }
32: 
33: interface IdentityToolkitResponse {
34:   users?: IdentityToolkitAccount[];
35: }
36: 
37: /** Extrae el token de `Authorization: Bearer <token>`. */
38: export function getBearerToken(request: NextRequest): string | null {
39:   const header = request.headers?.get?.('authorization');
40:   if (!header) return null;
41:   const match = /^Bearer\s+(.+)$/i.exec(header.trim());
42:   if (!match) return null;
43:   const token = match[1].trim();
44:   return token.length > 0 ? token : null;
45: }
46: 
47: /**
48:  * Verifica el ID token del usuario y devuelve su identidad.
49:  * No lanza: las rutas deben responder con el status/mensaje del resultado.
50:  */
51: export async function requireApiUser(request: NextRequest): Promise<ApiAuthResult> {
52:   const idToken = getBearerToken(request);
53:   if (!idToken) {
54:     return {
55:       ok: false,
56:       status: 401,
57:       message: 'Debes iniciar sesión para usar este servicio.',
58:     };
59:   }
60: 
61:   const apiKey = process.env.NEXT_PUBLIC_FIREBASE_API_KEY;
62:   if (!apiKey) {
63:     return {
64:       ok: false,
65:       status: 503,
66:       message: 'La autenticación del servidor no está configurada.',
67:     };
68:   }
69: 
70:   try {
71:     const response = await fetch(IDENTITY_TOOLKIT_URL, {
72:       method: 'POST',
73:       headers: { 'Content-Type': 'application/json' },
74:       body: JSON.stringify({ idToken }),
75:     });
76: 
77:     if (!response.ok) {
78:       return { ok: false, status: 401, message: 'Tu sesión expiró o no es válida.' };
79:     }
80: 
81:     const payload = (await response.json().catch(() => null)) as IdentityToolkitResponse | null;
82:     const account = payload?.users?.[0];
83:     if (!account || typeof account.localId !== 'string' || !account.localId) {
84:       return { ok: false, status: 401, message: 'Tu sesión expiró o no es válida.' };
85:     }
86: 
87:     return {
88:       ok: true,
89:       idToken,
90:       user: {
91:         uid: account.localId,
92:         email: typeof account.email === 'string' ? account.email : null,
93:         emailVerified: account.emailVerified === true,
94:         displayName: typeof account.displayName === 'string' ? account.displayName : null,
95:       },
96:     };
97:   } catch {
98:     return {
99:       ok: false,
100:       status: 503,
101:       message: 'No se pudo verificar la sesión. Intenta nuevamente.',
102:     };
103:   }
104: }
105: 
106: export type DocumentAccess = 'allowed' | 'denied' | 'unavailable';
107: 
108: function firestoreApiBaseUrl(): string {
109:   if (process.env.NEXT_PUBLIC_USE_FIREBASE_EMULATORS === 'true') {
110:     const host = process.env.NEXT_PUBLIC_FIREBASE_EMULATOR_HOST || '127.0.0.1';
111:     return `http://${host}:8080`;
112:   }
113:   return 'https://firestore.googleapis.com';
114: }
115: 
116: /**
117:  * Comprueba si el usuario puede leer un documento de Firestore **aplicando las
118:  * reglas de seguridad**: la consulta REST se envía con el ID token del usuario,
119:  * así que son las reglas reales (no el service account) las que autorizan.
120:  */
121: export async function canReadDocumentAsUser(
122:   idToken: string,
123:   collectionName: string,
124:   documentId: string
125: ): Promise<DocumentAccess> {
126:   const projectId = process.env.NEXT_PUBLIC_FIREBASE_PROJECT_ID;
127:   if (!projectId) return 'unavailable';
128: 
129:   const databaseId = process.env.NEXT_PUBLIC_FIRESTORE_DATABASE_ID || '(default)';
130:   // `(default)` no debe codificarse: Firestore REST lo espera literal.
131:   const safeDatabaseId = databaseId === '(default)' ? '(default)' : encodeURIComponent(databaseId);
132:   const url = `${firestoreApiBaseUrl()}/v1/projects/${encodeURIComponent(
133:     projectId
134:   )}/databases/${safeDatabaseId}/documents/${encodeURIComponent(
135:     collectionName
136:   )}/${encodeURIComponent(documentId)}`;
137: 
138:   try {
139:     const response = await fetch(url, {
140:       headers: { Authorization: `Bearer ${idToken}` },
141:     });
142: 
143:     if (response.ok) return 'allowed';
144:     if (response.status === 403 || response.status === 404) return 'denied';
145:     return 'unavailable';
146:   } catch {
147:     return 'unavailable';
148:   }
149: }

