1: 'use client';
2: 
3: import { auth } from '@/lib/firebaseService';
4: 
5: /**
6:  * Obtiene el ID token del usuario autenticado (o `null` si no hay sesión).
7:  * Las rutas API que consumen cuota (Gemini, clima, subida de fotos) exigen
8:  * este token; sin él responden 401.
9:  */
10: export async function getIdTokenOrNull(): Promise<string | null> {
11:   const user = auth?.currentUser;
12:   if (!user) return null;
13:   try {
14:     return await user.getIdToken();
15:   } catch {
16:     return null;
17:   }
18: }
19: 
20: /**
21:  * `fetch` que adjunta el ID token de Firebase cuando hay sesión.
22:  * Si no hay sesión la petición sale igual y el servidor la rechaza: así el
23:  * error es explícito (401) y no se rompe la UI por una excepción local.
24:  */
25: export async function authFetch(
26:   input: RequestInfo | URL,
27:   init: RequestInit = {}
28: ): Promise<Response> {
29:   const token = await getIdTokenOrNull();
30:   const headers = new Headers(init.headers);
31:   if (token) {
32:     headers.set('Authorization', `Bearer ${token}`);
33:   }
34:   return fetch(input, { ...init, headers });
35: }

