49:       console.warn(`No se pudo leer ${legacyCollection.name} para migrar a la empresa:`, error);
50:       failed += 1;
51:       continue;
52:     }
53: 
54:     let batch = writeBatch(db);
55:     let batchSize = 0;
56: 
57:     const commitBatch = async () => {
58:       if (batchSize === 0) return;
59:       try {
60:         await batch.commit();
61:         migrated += batchSize;
62:       } catch (error) {
63:         console.warn(`No se pudo migrar un lote de ${legacyCollection.name}; se omite:`, error);
64:         failed += batchSize;
65:       }
66:       batch = writeBatch(db);
67:       batchSize = 0;
68:     };
69: 
70:     for (const record of legacyRecords.docs) {
71:       const originalData = record.data();
72:       if (originalData.companyId === ownerId) continue;
73: 
