81: export function useProjectData(companyId?: string, currentUserId?: string, role?: CompanyRole) {
82:   // Refs para evitar limpiezas prematuras y closures stale (por instancia del componente)
83:   const hasInitializedRef = useRef(false);
84:   const lastCompanyIdRef = useRef<string | null>(null);
85:   const companyIdRef = useRef<string | undefined>(undefined);
86:   const currentUserIdRef = useRef<string | undefined>(undefined);
87:   const [projects, setProjects] = useState<Project[]>([]);
88:   const [fieldVisits, setFieldVisits] = useState<FieldVisit[]>([]);
89:   const [expenses, setExpenses] = useState<ExpenseRecord[]>([]);
90:   const [attendance, setAttendance] = useState<AttendanceRecord[]>([]);
91:   const [employees, setEmployees] = useState<Array<Employee | EmployeeDirectoryEntry>>([]);
92:   const [quotes, setQuotes] = useState<QuoteRecord[]>([]);
93:   const [apuItems, setApuItems] = useState<APUItem[]>([]);
94:   const [apuItemsLoading, setApuItemsLoading] = useState(false);
95:   const [machinery, setMachinery] = useState<Machinery[]>([]);
96:   const [machineryLogs, setMachineryLogs] = useState<MachineryLog[]>([]);
97:   const [company, setCompany] = useState<CompanySettings | null>(null);
98:   const [loading, setLoading] = useState(false);
99: 
100:   // ========== BUDGET SUMMARY MEMOIZATION ==========
101:   const budgetSummary = useMemo(() => {
102:     if (apuItems.length === 0 && expenses.length === 0) {
103:       return {
104:         budgetTotal: 0,
105:         spentTotal: 0,
106:         remaining: 0,
107:         utilization: 0,
108:         variance: 0,
109:         isOverBudget: false,
110:       };
111:     }
112: 
113:     try {
114:       return calculateBudgetSummary(
115:         apuItems,
116:         expenses.reduce((sum, exp) => sum + exp.amount, 0)
117:       );
118:     } catch (error) {
119:       log.error('Budget summary calculation failed', error as Error, {
120:         apuItemsCount: apuItems.length,
121:         expensesCount: expenses.length,
122:       });
123:       return {
124:         budgetTotal: 0,
125:         spentTotal: 0,
126:         remaining: 0,
127:         utilization: 0,
128:         variance: 0,
129:         isOverBudget: false,
130:       };
131:     }
132:   }, [apuItems, expenses]);
133: 
134:   // ========== CACHED SUBSCRIPTIONS ==========
135:   useEffect(() => {
136:     // Mantener refs actualizados para evitar closures stale en funciones de guardado
137:     companyIdRef.current = companyId;
138:     currentUserIdRef.current = currentUserId;
139: 
140:     if (!companyId || !currentUserId || !role) {
141:       // Si nunca se ha inicializado, no limpiar datos (evita parpadeo en carga inicial)
142:       if (!hasInitializedRef.current) {
143:         return;
144:       }
145:       // Si se había inicializado pero ahora falta auth, limpiar
146:       log.debug('Missing auth context, clearing data');
147:       setProjects([]);
148:       setFieldVisits([]);
149:       setExpenses([]);
150:       setAttendance([]);
151:       setEmployees([]);
152:       setQuotes([]);
153:       setApuItems([]);
154:       setApuItemsLoading(false);
155:       setMachinery([]);
156:       setMachineryLogs([]);
157:       setCompany(null);
158:       setLoading(false);
159:       hasInitializedRef.current = false;
160:       lastCompanyIdRef.current = null;
161:       return;
162:     }
163: 
164:     // Si ya se ha inicializado con el mismo companyId, no repetir suscripciones
165:     if (hasInitializedRef.current && lastCompanyIdRef.current === companyId) {
166:       return;
167:     }
168: 
169:     hasInitializedRef.current = true;
170:     lastCompanyIdRef.current = companyId;
171: 
172:     log.info('Starting data subscriptions', { companyId, role });
173: 
174:     // NO limpiar datos existentes al cambiar companyId - preservar hasta que lleguen nuevos datos
175:     setLoading(true);
176:     setApuItemsLoading(true);
177: 
178:     const unsubProjects = subscribeProjects(companyId, (nextProjects) => {
179:       log.debug('Projects updated', { count: nextProjects.length });
180:       // Cache projects
181:       const cacheKey = createCacheKey('projects', { companyId });
182:       queryCache.set(cacheKey, nextProjects, 5 * 60 * 1000);
183:       setProjects(nextProjects);
184:       setLoading(false);
185:     });
186: 
187:     const unsubFieldVisits = subscribeFieldVisits(companyId, (data) => {
188:       log.debug('Field visits updated', { count: data.length });
189:       const cacheKey = createCacheKey('fieldVisits', { companyId });
190:       queryCache.set(cacheKey, data, 5 * 60 * 1000);
191:       setFieldVisits(data);
192:     });
193: 
194:     const unsubExpenses = subscribeExpenses(companyId, (data) => {
195:       log.debug('Expenses updated', { count: data.length });
196:       const cacheKey = createCacheKey('expenses', { companyId });
197:       queryCache.set(cacheKey, data, 5 * 60 * 1000);
198:       setExpenses(data);
199:     });
200: 
201:     const unsubAttendance = canReadAttendance(role)
202:       ? subscribeAttendance(companyId, (data) => {
203:           log.debug('Attendance updated', { count: data.length });
204:           const cacheKey = createCacheKey('attendance', { companyId });
205:           queryCache.set(cacheKey, data, 5 * 60 * 1000);
206:           setAttendance(data);
207:         })
208:       : () => setAttendance([]);
209: 
210:     const unsubEmployees = canReadFullPersonnel(role)
211:       ? subscribeEmployees(companyId, (data) => {
212:           log.debug('Employees updated', { count: data.length });
213:           const cacheKey = createCacheKey('employees', { companyId });
214:           queryCache.set(cacheKey, data, 5 * 60 * 1000);
215:           setEmployees(data);
216:         })
217:       : canReadEmployeeDirectory(role)
218:         ? subscribeEmployeeDirectory(companyId, (data) => {
219:             log.debug('Employee directory updated', { count: data.length });
220:             const cacheKey = createCacheKey('employees', { companyId });
221:             queryCache.set(cacheKey, data, 5 * 60 * 1000);
222:             setEmployees(data);
223:           })
224:         : () => setEmployees([]);
225: 
226:     const unsubCompany = subscribeCompanySettings(companyId, (data) => {
227:       log.debug('Company settings updated', { companyId });
228:       const cacheKey = createCacheKey('companySettings', { companyId });
229:       queryCache.set(cacheKey, data, 10 * 60 * 1000);
230:       setCompany(data ?? null);
231:     });
232: 
233:     const unsubQuotes = subscribeQuotes(companyId, (data) => {
234:       log.debug('Quotes updated', { count: data.length });
235:       const cacheKey = createCacheKey('quotes', { companyId });
236:       queryCache.set(cacheKey, data, 5 * 60 * 1000);
237:       setQuotes(data);
238:     });
239: 
240:     const unsubAPUItems = subscribeAPUItems(companyId, (nextItems) => {
241:       log.debug('APU items updated', { count: nextItems.length });
242:       const cacheKey = createCacheKey('apuItems', { companyId });
243:       queryCache.set(cacheKey, nextItems, 5 * 60 * 1000);
244:       setApuItems(nextItems);
245:       setApuItemsLoading(false);
246:     });
247: 
248:     const unsubMachinery = subscribeMachinery(companyId, (data) => {
249:       log.debug('Machinery updated', { count: data.length });
250:       const cacheKey = createCacheKey('machinery', { companyId });
251:       queryCache.set(cacheKey, data, 5 * 60 * 1000);
252:       setMachinery(data);
253:     });
254: 
255:     const unsubMachineryLogs = subscribeMachineryLogs(companyId, (data) => {
256:       log.debug('Machinery logs updated', { count: data.length });
257:       setMachineryLogs(data);
258:     });
259: 
260:     // Los datos llegarán vía callbacks de Firebase; loading se desactiva cuando proyectos llegan.
261:     return () => {
262:       log.info('Unsubscribing from data streams');
263:       unsubProjects();
264:       unsubFieldVisits();
265:       unsubExpenses();
266:       unsubAttendance();
267:       unsubEmployees();
268:       unsubCompany();
269:       unsubQuotes();
270:       unsubAPUItems();
271:       unsubMachinery();
272:       unsubMachineryLogs();
273:     };
274:   }, [companyId, currentUserId, role]);
275: 
276:   // ========== DERIVED STATE: PROJECTS WITH CALCULATIONS ==========
277:   const projectsWithCalculations = useMemo(() => {
278:     if (projects.length === 0) return projects;
279: 
280:     // Calculate spent total for each project
281:     const withSpent = projects.map((project) => {
282:       const calculatedSpent = calculateProjectSpentById(expenses, project.id);
283: 
284:       if (calculatedSpent !== project.spentTotal) {
285:         log.debug('Project spent updated', {
286:           projectId: project.id,
287:           oldSpent: project.spentTotal,
288:           newSpent: calculatedSpent,
289:         });
290:         return {
291:           ...project,
292:           spentTotal: calculatedSpent,
293:         };
294:       }
295: 
296:       return project;
297:     });
298: 
299:     // Calculate progress for each project
300:     const withProgress = withSpent.map((project) => {
301:       const calculatedProgress = resolveProjectProgress(
302:         project.scheduleTasks,
303:         project.scheduleMilestones,
304:         project.progressPercent
305:       );
306: 
307:       if (calculatedProgress !== project.progressPercent) {
308:         log.debug('Project progress updated', {
309:           projectId: project.id,
310:           oldProgress: project.progressPercent,
311:           newProgress: calculatedProgress,
312:         });
313:         return {
314:           ...project,
315:           progressPercent: calculatedProgress,
316:         };
317:       }
318: 
319:       return project;
320:     });
321: 
322:     return withProgress;
323:   }, [projects, expenses]);
