325:   // ========== PROJECT CREATION ==========
326:   const createProject = useCallback(
327:     async (data: ProjectFormValues, onCreated?: (projectId: string) => void) => {
328:       if (!companyId || !currentUserId) {
329:         log.warn('Project creation attempted without auth');
330:         toast.error('Usuario no autenticado');
331:         return false;
332:       }
333: 
334:       const validation = validateProjectForm(data);
335:       if (!validation.success) {
336:         log.warn('Project validation failed', {
337:           errors: validation.error.issues.map((i) => i.message),
338:         });
339:         toast.error('Datos inválidos: ' + validation.error.issues.map((i) => i.message).join(', '));
340:         return false;
341:       }
342: 
343:       setLoading(true);
344:       try {
345:         log.info('Creating project', { companyId });
346:         const projectId = `proj-${crypto.randomUUID()}`;
347:         const project: Project = {
348:           ...validation.data,
349:           id: projectId,
350:           companyId,
351:           ownerId: currentUserId,
352:           createdBy: currentUserId,
353:         };
354: 
355:         const success = await saveProjectToFirestore(project, companyId, currentUserId);
356:         if (success) {
357:           log.info('Project created successfully', { projectId, companyId });
358:           onCreated?.(projectId);
359:           toast.success('Proyecto creado correctamente');
360:           // Clear cache
361:           const cacheKey = createCacheKey('projects', { companyId });
362:           queryCache.clear(cacheKey);
363:           return true;
364:         }
365: 
366:         log.error('Project creation failed in Firestore', { projectId, companyId });
367:         toast.error('Error al crear el proyecto');
368:         return false;
369:       } catch (err) {
370:         notifySyncEnd();
371:         log.error('Project creation error', err as Error, { companyId });
372:         toast.error('Error inesperado al crear el proyecto');
373:         return false;
374:       } finally {
375:         setLoading(false);
376:       }
377:     },
378:     [companyId, currentUserId]
379:   );
