30: export function useAPUItems({ companyId, currentUserId, projects = [] }: UseAPUItemsOptions): UseAPUItemsReturn {
31:   const [apuItems, setApuItems] = useState<APUItem[]>([]);
32:   const [loading, setLoading] = useState(false);
33:   const hasInitializedRef = useRef(false);
34:   const lastCompanyIdRef = useRef<string | null>(null);
35: 
36:   useEffect(() => {
37:     if (!companyId || !currentUserId) {
38:       if (!hasInitializedRef.current) return;
39:       log.debug('Missing auth context, clearing APU items');
40:       setApuItems([]);
41:       setLoading(false);
42:       hasInitializedRef.current = false;
43:       lastCompanyIdRef.current = null;
44:       return;
45:     }
46: 
47:     if (hasInitializedRef.current && lastCompanyIdRef.current === companyId) return;
48: 
49:     hasInitializedRef.current = true;
50:     lastCompanyIdRef.current = companyId;
51: 
52:     log.info('Starting APU items subscription', { companyId });
53:     setLoading(true);
54: 
55:     const unsubAPUItems = subscribeAPUItems(companyId, (nextItems) => {
56:       log.debug('APU items updated', { count: nextItems.length });
57:       const cacheKey = createCacheKey('apuItems', { companyId });
58:       queryCache.set(cacheKey, nextItems, 5 * 60 * 1000);
59:       setApuItems(nextItems);
60:       setLoading(false);
61:     });
62: 
63:     return () => {
64:       log.info('Unsubscribing from APU items');
65:       unsubAPUItems();
66:     };
67:   }, [companyId, currentUserId]);
68: 
69:   const saveAPUItems = useCallback(
70:     async (items: APUItem[], projectId: string) => {
71:       if (!companyId || !currentUserId) {
72:         log.warn('APU items save attempted without auth');
73:         toast.error('Inicia sesión en una empresa para guardar el presupuesto APU.');
74:         return false;
75:       }
76: 
77:       if (!projectId || !projects.some((project) => project.id === projectId)) {
78:         log.warn('Invalid project for APU save', { projectId });
79:         toast.error('Selecciona un proyecto válido para guardar las partidas APU.');
80:         return false;
81:       }
82: 
83:       try {
84:         const validatedItems = items.map((item) => {
85:           try {
86:             return validateAPUItem(item);
87:           } catch (err) {
88:             log.error('APU item validation failed', err as Error, { itemCode: item.code });
89:             throw err;
90:           }
91:         });
92: 
93:         log.info('Saving APU items', { projectId, count: validatedItems.length });
94:         const saved = await saveAPUItemsToFirestore(validatedItems, projectId, companyId, currentUserId);
95: 
96:         if (!saved) {
97:           log.error('APU items save failed in Firestore', { projectId });
98:           toast.error('No se pudo guardar el presupuesto APU.');
99:           return false;
100:         }
101: 
102:         log.info('APU items saved successfully', { projectId, count: validatedItems.length });
103:         const cacheKey = createCacheKey('apuItems', { companyId });
104:         queryCache.clear(cacheKey);
105:         return true;
106:       } catch (err) {
107:         log.error('APU items save error', err as Error, { projectId });
108:         toast.error('Error al guardar el presupuesto APU.');
109:         return false;
110:       }
111:     },
112:     [companyId, currentUserId, projects]
113:   );
114: 
115:   const deleteAPUItem = useCallback(
116:     async (itemId: string) => {
117:       if (!companyId || !currentUserId) {
118:         log.warn('APU item deletion attempted without auth');
119:         toast.error('Inicia sesión en una empresa para eliminar partidas APU.');
120:         return false;
121:       }
122: 
123:       if (!apuItems.some((item) => item.id === itemId && item.companyId === companyId)) {
124:         log.warn('APU item not found in company', { itemId });
125:         toast.error('No se encontró la partida APU en esta empresa.');
126:         return false;
127:       }
128: 
129:       try {
130:         log.info('Deleting APU item', { itemId });
131:         const deleted = await deleteAPUItemFromFirestore(itemId);
132:         if (!deleted) {
133:           log.error('APU item deletion failed', { itemId });
134:           toast.error('No se pudo eliminar la partida APU.');
135:           return false;
136:         }
137: 
138:         log.info('APU item deleted successfully', { itemId });
139:         const cacheKey = createCacheKey('apuItems', { companyId });
140:         queryCache.clear(cacheKey);
141:         return true;
142:       } catch (err) {
143:         log.error('APU item deletion error', err as Error, { itemId });
144:         toast.error('Error al eliminar la partida APU.');
145:         return false;
146:       }
147:     },
148:     [apuItems, companyId, currentUserId]
149:   );
150: 
151:   return {
152:     apuItems,
153:     loading,
154:     saveAPUItems,
155:     deleteAPUItem,
156:   };
