import { initializeApp } from 'firebase/app';
import { connectAuthEmulator, getAuth, signInWithEmailAndPassword } from 'firebase/auth';
import {
  collection,
  connectFirestoreEmulator,
  doc,
  getDocs,
  getFirestore,
  query,
  setDoc,
  where,
  writeBatch,
} from 'firebase/firestore';

const app = initializeApp({
  apiKey: 'demo-api-key',
  authDomain: 'localhost',
  projectId: 'demo-origen-erp-test',
});
const auth = getAuth(app);
const db = getFirestore(app);
connectAuthEmulator(auth, 'http://127.0.0.1:9099', { disableWarnings: true });
connectFirestoreEmulator(db, '127.0.0.1', 8080);

const credential = await signInWithEmailAndPassword(
  auth,
  process.env.E2E_ADMIN_EMAIL,
  process.env.E2E_ADMIN_PASSWORD
);
const uid = credential.user.uid;
console.log('uid', uid);

const projectsSnapshot = await getDocs(query(collection(db, 'projects'), where('companyId', '==', uid)));
console.log('projects:', projectsSnapshot.size);
projectsSnapshot.docs.forEach((d) => console.log('  ', d.id, d.data().code, d.data().status, 'companyId=', d.data().companyId, 'ownerId=', d.data().ownerId));

const project = projectsSnapshot.docs[0];
if (!project) {
  console.log('NO PROJECT');
  process.exit(0);
}

const item = {
  id: `apu-probe-${Date.now()}`,
  projectId: project.id,
  companyId: uid,
  createdBy: uid,
  updatedBy: uid,
  code: 'APU-PROBE',
  description: 'Probe APU',
  unit: 'm3',
  quantity: 2,
  materialUnitCostGTQ: 200,
  laborUnitCostGTQ: 100,
  equipmentUnitCostGTQ: 50,
  totalUnitCostGTQ: 350,
  totalPriceGTQ: 700,
};

try {
  const batch = writeBatch(db);
  batch.set(doc(db, 'apuItems', item.id), item, { merge: true });
  await batch.commit();
  console.log('APU WRITE OK');
} catch (error) {
  console.log('APU WRITE ERR:', error.code, '|', error.message);
}
process.exit(0);

