/**
 * Construye el registro APU completo que se persiste en Firestore.
 *
 * `companyId`, `projectId` y `createdBy` los agrega el servidor y son
 * obligatorios en `APUItemSchema`, por lo que el registro debe quedar
 * completo **antes** de validar; si se valida el borrador, la validación
 * siempre falla por los campos de propiedad ausentes.
 */
function buildAPUItemRecords(
  items: APUItem[],
  projectId: string,
  companyId: string,
  userId: string
): APUItem[] {
  return items.map((item) => {
    const normalized = normalizeAPUItem(item);
    return {
      ...normalized,
      companyId,
      projectId,
      createdBy: normalized.createdBy ?? userId,
      updatedBy: userId,
    };
  });
}

export async function saveAPUItemsToFirestore(
  items: APUItem[],
  projectId: string,
  companyId: string,
  userId: string
): Promise<boolean> {
  if (items.length > 500) {
    throw new Error('No se pueden guardar más de 500 partidas APU en una operación.');
  }

  const records = buildAPUItemRecords(items, projectId, companyId, userId);

  // Validar cada item con Zod
  for (const record of records) {
    const validation = validateAPUItem(record);
    if (!validation.success) {
      console.error('APU Item validation failed:', validation.error);
      throw new Error(
        `Datos de partida APU inválidos (${record.code}): ${validation.error.issues.map((i) => i.message).join(', ')}`
      );
    }
  }

  const path = 'apuItems';
  try {
    const batch = writeBatch(db);
    for (const record of records) {
      batch.set(doc(db, path, record.id), record, { merge: true });
    }
    await batch.commit();
    return true;
  } catch (error) {
    notifySyncEnd();
    handleFirestoreError(error, OperationType.WRITE, path);
    return false;
  }
}

export async function saveAPUItemsToFirestoreServer(
  items: APUItem[],
  projectId: string,
  companyId: string,
  userId: string
): Promise<boolean> {
  if (items.length > 500) {
    throw new Error('No se pueden guardar más de 500 partidas APU en una operación.');
  }

  const records = buildAPUItemRecords(items, projectId, companyId, userId);

  for (const record of records) {
    const validation = validateAPUItem(record);
    if (!validation.success) {
      console.error('APU Item validation failed:', validation.error);
      throw new Error(
        `Datos de partida APU inválidos (${record.code}): ${validation.error.issues.map((i) => i.message).join(', ')}`
      );
    }
  }

  const path = 'apuItems';
  try {
    const batch = writeBatch(db);
    for (const record of records) {
      batch.set(doc(db, path, record.id), record, { merge: true });
    }
    await batch.commit();
    return true;
  } catch (error) {
    handleFirestoreError(error, OperationType.WRITE, path);
    return false;
  }
}

