import { initializeApp } from 'firebase/app';
import { connectAuthEmulator, getAuth, signInWithEmailAndPassword } from 'firebase/auth';
import { collection, connectFirestoreEmulator, getDocs, getFirestore, query, where } from 'firebase/firestore';

const app = initializeApp({
  apiKey: 'demo-api-key',
  authDomain: 'localhost',
  projectId: 'demo-origen-erp-test',
});
const auth = getAuth(app);
const db = getFirestore(app);
connectAuthEmulator(auth, 'http://127.0.0.1:9099', { disableWarnings: true });
connectFirestoreEmulator(db, '127.0.0.1', 8080);

const credential = await signInWithEmailAndPassword(
  auth,
  process.env.E2E_ADMIN_EMAIL,
  process.env.E2E_ADMIN_PASSWORD
);
const uid = credential.user.uid;

for (const name of ['expenses', 'apuItems', 'projects', 'employees', 'attendance', 'machinery', 'quotes']) {
  const snap = await getDocs(query(collection(db, name), where('companyId', '==', uid)));
  console.log(`--- ${name}: ${snap.size}`);
  snap.docs.slice(0, 4).forEach((d) => {
    const data = d.data();
    const brief = {
      id: d.id,
      projectId: data.projectId,
      facturaNumber: data.facturaNumber,
      description: data.description,
      code: data.code,
      name: data.name,
      status: data.status,
      authorId: data.authorId,
      createdBy: data.createdBy,
      amount: data.amount,
      paymentMethod: data.paymentMethod,
      approvalStatus: data.approvalStatus,
    };
    console.log('   ', JSON.stringify(brief));
  });
}
process.exit(0);

