const clickByText = (text) => tools.browser.evaluate({
  tabID,
  script: `(() => {
    const btn = Array.from(document.querySelectorAll('button')).find(b => b.textContent.trim().includes(${JSON.stringify(text)}));
    if (!btn) return 'NOT FOUND';
    btn.click();
    return 'clicked';
  })()`,
});

await clickByText("Gastos & Facturas");
await tools.browser.wait({ tabID, condition: "text", text: "Registrar Gasto / Factura", timeoutMs: 15000 });
const r2 = await clickByText("Registrar Gasto / Factura");
await tools.browser.wait({ tabID, condition: "text", text: "Registrar Gasto o Factura FEL", timeoutMs: 15000 });

const fillRes = await tools.browser.evaluate({
  tabID,
  script: `(() => {
    const setNative = (el, value) => {
      const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
      setter.call(el, value);
      el.dispatchEvent(new Event('input', { bubbles: true }));
    };
    const form = Array.from(document.querySelectorAll('form')).find(f => f.querySelector('[aria-label="Proveedor"]'));
    if (!form) return 'NO FORM';
    const inputs = form.querySelectorAll('input');
    setNative(inputs[0], 'Browser Supplier');
    setNative(inputs[1], '123456789');
    setNative(inputs[2], 'FAC-BROWSER-1');
    setNative(inputs[3], '1500');
    setNative(inputs[4], 'Browser expense description');
    form.requestSubmit();
    return 'submitted';
  })()`,
});
await tools.browser.wait({ tabID, condition: "text", text: "Presupuestos", timeoutMs: 10000 });
const consoleRes = await tools.browser.console({ tabID, level: "error", limit: 40 });
return { fill: fillRes.value, errors: consoleRes.messages.map(m => m.text).slice(0, 20) };

