try {
  const snap = await getDoc(doc(db, 'apuItems', apuId));
  console.log('apu exists:', snap.exists());
} catch (e) {
  console.log('apu get ERR:', e.code, e.message);
}

const machId = `mach-${Date.now()}`;
const okMach = await service.saveMachineryToFirestore(
  {
    id: machId,
    name: 'Excavadora prueba',
    model: 'CAT-320',
    plateOrCode: 'PRB-EQ',
    status: 'Disponible',
