  const u = r.url();
  if (u.includes('firestore') || u.includes('googleapis')) console.log(`[req] ${r.method()} ${u.slice(0, 140)}`);
});
page.on('response', (r) => {
  const u = r.url();
  if (u.includes('firestore') || u.includes('googleapis'))
    console.log(`[res] ${r.status()} ${u.slice(0, 140)}`);
});

