import { chromium } from '@playwright/test';

const BASE = 'http://localhost:3000';

async function createAndReload(waitBeforeReloadMs: number) {
  const browser = await chromium.launch();
  const context = await browser.newContext({ baseURL: BASE });
  const page = await context.newPage();

  await page.goto('/', { waitUntil: 'domcontentloaded' });
  const dashboard = page.getByRole('button', { name: 'Tablero' }).first();
  const emailField = page.getByLabel('Correo electrónico');
  await dashboard.or(emailField).first().waitFor({ timeout: 60000 });
  if (await emailField.isVisible()) {
    await emailField.fill('admin@test.com');
    await page.getByLabel('Contraseña', { exact: true }).fill('test123');
    await page.getByRole('button', { name: /Iniciar Sesi/i }).click();
    await dashboard.waitFor({ timeout: 60000 });
  }

  await page.getByRole('button', { name: 'Proyectos & Firmas' }).first().click();
  await page.waitForTimeout(1500);
  await page.getByRole('button', { name: 'Nuevo Proyecto' }).first().click();

  const dialog = page.getByRole('dialog', { name: 'Nuevo Proyecto' });
  await dialog.waitFor({ timeout: 15000 });
  const code = `E2E-DIAG-${Date.now().toString().slice(-6)}`;
  await dialog.getByLabel('Código del Proyecto').fill(code);
  await dialog.getByLabel('Nombre del Proyecto').fill(`Proyecto DIAG ${code}`);
  await dialog.getByLabel('Nombre del cliente').fill('Cliente E2E');
  await dialog.getByLabel('Ubicación').fill('Zona 1, Guatemala');
  await dialog.getByLabel('Municipio').fill('Guatemala');
  await dialog.getByLabel('Departamento').fill('Guatemala');
  await dialog.getByLabel('Presupuesto Total (Q)').fill('100000');
  await dialog.getByLabel('Avance (%)').fill('5');
  await dialog.getByLabel('Fecha de Inicio').fill('2026-11-01');
  await dialog.getByLabel('Fecha de Finalización').fill('2027-11-01');
  await dialog.getByRole('button', { name: 'Crear Proyecto' }).click();
  await dialog.waitFor({ state: 'hidden', timeout: 20000 });

  if (waitBeforeReloadMs > 0) await page.waitForTimeout(waitBeforeReloadMs);

  await page.reload({ waitUntil: 'domcontentloaded' });
  await page.waitForTimeout(6000);
  await page.getByRole('button', { name: 'Proyectos & Firmas' }).first().click();
  await page.waitForTimeout(2000);
  const count = await page.getByText(code).count();
  console.log(`waitBeforeReload=${waitBeforeReloadMs}ms -> IN LIST AFTER RELOAD: ${count} (${code})`);
  await browser.close();
  return count;
}

await createAndReload(0);
await createAndReload(2000);
await createAndReload(5000);

