Index: lib/firebaseService.ts
===================================================================
--- lib/firebaseService.ts
+++ lib/firebaseService.ts
@@ -155,8 +155,25 @@
     );
   }
   return storage;
 }
+/**
+ * Espera a que el backend confirme las escrituras pendientes.
+ *
+ * `setDoc()`/`updateDoc()`/`deleteDoc()` resuelven cuando la mutación entra en
+ * la cola local del SDK de Firestore, **no** cuando el backend la confirma.
+ * Medido contra el emulador hay una ventana de ~300 ms entre la resolución de
+ * la promesa y el commit real: si la página se recarga o se navega en esa
+ * ventana, la escritura se pierde aunque la UI ya haya mostrado "guardado
+ * correctamente" (el documento nunca llegó a existir).
+ *
+ * `waitForPendingWrites()` cierra esa ventana: la promesa solo resuelve cuando
+ * el backend ya aceptó la escritura.
+ */
+export async function commitPendingWrites(): Promise<void> {
+  await waitForPendingWrites(getDbOrThrow());
+}
+
 const isNewFirebaseApp = !hasExistingFirebaseApp;
 const useFirebaseEmulators =
   process.env.NODE_ENV === 'development' &&
   process.env.NEXT_PUBLIC_USE_FIREBASE_EMULATORS === 'true';

