const fs = require('node:fs');
const path = 'lib/firebaseService.ts';
let text = fs.readFileSync(path, 'utf8');

// 1. quitar las llamadas de confirmación
text = text.replace(/^[ \t]*await commitPendingWrites\(\);[ \t]*\r?\n/gm, '');
// 2. quitar el import
text = text.replace(/^[ \t]*waitForPendingWrites,\r?\n/m, '');
// 3. quitar el helper (bloque completo)
const helperStart = text.indexOf('/**\r\n * Espera a que el backend confirme las escrituras pendientes.');
if (helperStart === -1) {
  const alt = text.indexOf('/**\n * Espera a que el backend confirme las escrituras pendientes.');
  if (alt === -1) throw new Error('helper no encontrado');
  const end = text.indexOf('}\n', text.indexOf('export async function commitPendingWrites', alt));
  text = text.slice(0, alt) + text.slice(end + 2);
} else {
  const end = text.indexOf('}\r\n', text.indexOf('export async function commitPendingWrites', helperStart));
  text = text.slice(0, helperStart) + text.slice(end + 3);
}

fs.writeFileSync(path, text);
console.log('ok');

