 */
export async function selectActiveProject(page: Page, code: string): Promise<void> {
  // El overlay de un modal abierto tapa la cabecera: si sigue abierto, el
  // clic en el selector no llega al botón.
  const openDialog = page.getByRole('dialog');
  if (await openDialog.count()) {
    await expect(openDialog.first()).toBeHidden({ timeout: 20_000 });
  }

  // El único botón con `aria-haspopup="listbox"` es el selector de proyecto
  // de la cabecera (Navbar.tsx).
  const trigger = page.locator('header button[aria-haspopup="listbox"]').first();
  await trigger.click();

  const menu = page.getByRole('menu', { name: 'Cambiar proyecto activo' });
  await expect(menu).toBeVisible({ timeout: 15_000 });

  // El proyecto recién creado llega por suscripción: hay que esperar a que
  // aparezca en la lista para poder seleccionarlo.
  const item = menu.getByRole('menuitem').filter({ hasText: code }).first();
  await expect(item).toBeVisible({ timeout: 30_000 });
  await item.click();
}

/**
 * Espera a que el backend confirme un proyecto recién creado.
 *
 * El emulador de Firestore envía el *ack* de la escritura antes de aplicarla
 * en su almacén (~150 ms de diferencia): si la página se recarga en esa
 * ventana, el documento se pierde y nunca llega a existir.
 *
 * La comprobación se hace desde una segunda pestaña: su listener de Firestore
 * solo recibe el estado del servidor, no la caché optimista de la pestaña que
 * escribió el documento.
 */
export async function waitForProjectPersisted(page: Page, code: string): Promise<void> {
  const probe = await page.context().newPage();
  try {
    await probe.goto('/', { waitUntil: 'domcontentloaded', timeout: 60_000 });
    await probe.getByRole('button', { name: 'Proyectos & Firmas' }).first().click();
    await expect(probe.getByText(code).first()).toBeVisible({ timeout: 30_000 });
  } finally {
    await probe.close();
  }
}

